import argparse
import json
import os
from pathlib import Path
import sys
import tempfile

from .grants import GrantError
from .metadata import RepositoryIndex
from .normalize import normalize_name
from .uploads import authorize_upload, UploadConflictError

__all__ = ['CONFLICT_EXIT', 'build_parser', 'main']

CONFLICT_EXIT = 3


def build_parser():
    """Build the command line argument parser."""
    parser = argparse.ArgumentParser(
        prog='python -m packagenamespaces',
        description='Manage repository-local package namespaces (PEP 752).',
    )
    parser.add_argument('--store', default='packagenamespaces.json',
                        help='JSON store path (default: %(default)s)')
    commands = parser.add_subparsers(dest='command', required=True)
    for command, argument, owner in (
        ('reserve', 'namespace', True),
        ('list', None, False),
        ('show', 'namespace', False),
        ('remove', 'namespace', False),
        ('register', 'project', True),
        ('grandfather', 'project', True),
        ('check-upload', 'project', True),
        ('dump', None, False),
    ):
        subparser = commands.add_parser(command)
        # Accept --store both before and after the subcommand.
        subparser.add_argument('--store', default=argparse.SUPPRESS,
                               help='JSON store path')
        if argument:
            subparser.add_argument(argument)
        if owner:
            subparser.add_argument('--owner', required=True)
        if command in ('list', 'show'):
            subparser.add_argument('--json', action='store_true')
        if command == 'dump':
            subparser.add_argument('--project')
    return parser


def _load(path):
    index = RepositoryIndex()
    try:
        with path.open(encoding='utf-8') as stream:
            data = json.load(stream)
    except FileNotFoundError:
        return index
    if (not isinstance(data, dict)
            or set(data) != {'grants', 'projects', 'grandfathered'}
            or not isinstance(data['grants'], dict)
            or not isinstance(data['projects'], dict)
            or not isinstance(data['grandfathered'], list)):
        raise ValueError('invalid store schema')
    for name, owner in data['grants'].items():
        index.store.reserve(name, owner)
    for project, owner in data['projects'].items():
        index.register_project(project, owner)
    for project in data['grandfathered']:
        index.grandfathered.add(project)
    return index


def _save(path, index):
    data = {
        'grants': {grant.name: grant.owner for grant in index.store},
        'projects': {project: index.project_owner(project)
                     for project in index.projects()},
        'grandfathered': index.grandfathered.projects(),
    }
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(
            mode='w', encoding='utf-8', dir=path.parent,
            prefix=f'.{path.name}.', delete=False,
        ) as stream:
            temporary = Path(stream.name)
            json.dump(data, stream, indent=2, sort_keys=True)
            stream.write('\n')
        os.replace(temporary, path)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def _print_json(value):
    print(json.dumps(value, sort_keys=True))


def _run(args, path, index):
    command = args.command
    if command == 'reserve':
        grant = index.store.reserve(args.namespace, args.owner)
        _save(path, index)
        print(f'reserved {grant.name} for {grant.owner}')
    elif command == 'remove':
        grant = index.store.remove(args.namespace)
        _save(path, index)
        print(f'removed {grant.name}')
    elif command in ('register', 'grandfather'):
        index.register_project(args.project, args.owner)
        project = normalize_name(args.project)
        if command == 'grandfather':
            index.grandfathered.add(project)
        _save(path, index)
        if command == 'grandfather':
            print(f'grandfathered {project}')
        else:
            print(f'registered {project} for {args.owner}')
    elif command == 'list':
        if args.json:
            _print_json([{'name': grant.name, 'owner': grant.owner}
                         for grant in index.store])
        else:
            for grant in index.store:
                print(f'{grant.name} {grant.owner}')
    elif command == 'show':
        detail = index.namespace_detail(args.namespace)
        if args.json:
            _print_json(detail)
        else:
            print(f"name: {detail['name']}")
            print(f"owner: {detail['owner']}")
            print(f"parent: {detail['parent'] or 'none'}")
            print(f"children: {', '.join(detail['children']) or 'none'}")
    elif command == 'check-upload':
        authorize_upload(args.project, args.owner, index.store,
                         index.grandfathered)
        print(f'OK {normalize_name(args.project)}')
    elif command == 'dump':
        if args.project is not None:
            _print_json(index.project_detail(args.project))
        else:
            _print_json({'api_version': index.api_version,
                         'namespaces': index.list_namespaces()})
    return 0


def main(argv=None):
    """Return 0 on success, 1 on error, or 3 on an upload conflict."""
    args = build_parser().parse_args(argv)
    try:
        path = Path(args.store)
        return _run(args, path, _load(path))
    except UploadConflictError as error:
        print(f'error: {error}', file=sys.stderr)
        return CONFLICT_EXIT
    except (GrantError, OSError, TypeError, ValueError) as error:
        print(f'error: {error}', file=sys.stderr)
        return 1
