@dataclass(frozen=True, order=True)
class Grant:
    """An immutable, normalized namespace name and its owner."""

    name: str
    owner: str

    def __post_init__(self):
        object.__setattr__(self, 'name', _validate_name(self.name))
        _validate_owner(self.owner)


def grants_overlap(first, second):
    """Return whether two normalized namespace prefixes overlap."""
    first = normalize_name(first) + '-'
    second = normalize_name(second) + '-'
    return first.startswith(second) or second.startswith(first)


class GrantStore:
    """Keep active grants, allowing overlapping grants only for one owner."""

    def __init__(self, depth_limit=DEFAULT_DEPTH_LIMIT):
        if depth_limit is not None and (
            not isinstance(depth_limit, int) or isinstance(depth_limit, bool)
            or depth_limit < 0
        ):
            raise ValueError(
                'depth_limit must be a non-negative integer or None'
            )
        self._depth_limit = depth_limit
        self._grants = {}

    @property
    def depth_limit(self):
        """Maximum hyphen depth, or None for no limit."""
        return self._depth_limit

    def __len__(self):
        return len(self._grants)

    def __contains__(self, name):
        return isinstance(name, str) and normalize_name(name) in self._grants

    def __iter__(self):
        return (self._grants[name] for name in self.namespaces())

    def _check_overlap(self, name, owner):
        for other in self:
            if (other.name != name and other.owner != owner
                    and grants_overlap(name, other.name)):
                raise OverlapError(
                    f'{name!r} overlaps the grant for {other.name!r}'
                )

    def reserve(self, name, owner):
        """Reserve name for owner and return its grant."""
        name = _validate_name(name)
        _validate_owner(owner)
        if (self.depth_limit is not None
                and hyphen_depth(name) > self.depth_limit):
            raise DepthLimitError(
                f'{name!r} exceeds depth limit {self.depth_limit}'
            )
        existing = self.get(name)
        if existing is not None and existing.owner != owner:
            raise OverlapError(f'{name!r} overlaps the grant for {name!r}')
        self._check_overlap(name, owner)
        grant = Grant(name, owner)
        self._grants[name] = grant
        return grant

    def transfer(self, name, owner):
        """Transfer a grant, provided other grants permit the new owner."""
        _validate_owner(owner)
        grant = self.get(name)
        if grant is None:
            raise UnknownGrantError(f'unknown grant: {name!r}')
        self._check_overlap(grant.name, owner)
        grant = Grant(grant.name, owner)
        self._grants[grant.name] = grant
        return grant

    def remove(self, name):
        """Remove and return a grant; raise UnknownGrantError if absent."""
        grant = self.get(name)
        if grant is None:
            raise UnknownGrantError(f'unknown grant: {name!r}')
        del self._grants[grant.name]
        return grant

    def get(self, name):
        """Return the grant for the normalized name, or None."""
        return self._grants.get(normalize_name(name))

    def namespaces(self):
        """Return the granted names in sorted order."""
        return sorted(self._grants)

    def matching(self, project):
        """Return all grants matching project, sorted by namespace name."""
        project = normalize_name(project)
        return [grant for grant in self
                if namespace_matches(grant.name, project)]

    def parent(self, name):
        """Return the directly granted parent name, or None."""
        grant = self.get(name)
        if grant is not None:
            parent, separator, _ = grant.name.rpartition('-')
            if separator and parent in self:
                return parent
        return None

    def children(self, name):
        """Return directly granted child names in sorted order."""
        grant = self.get(name)
        if grant is None:
            return []
        return [child for child in self.namespaces()
                if child.rpartition('-')[0] == grant.name]
