    def __init__(self, store=None, *, supports_namespaces=True,
                 grandfathered=None):
        self._store = GrantStore() if store is None else store
        self._supports_namespaces = supports_namespaces
        self._grandfathered = (GrandfatheredRegistry() if grandfathered is None
                               else grandfathered)
        self._projects = {}

    @property
    def store(self):
        return self._store

    @property
    def supports_namespaces(self):
        return self._supports_namespaces

    @property
    def grandfathered(self):
        return self._grandfathered

    @property
    def api_version(self):
        return (API_VERSION if self.supports_namespaces
                else LEGACY_API_VERSION)

    def register_project(self, project, owner):
        """Record a project owner without authorizing an upload."""
        project = _validate_name(project)
        _validate_owner(owner)
        self._projects[project] = owner

    def project_owner(self, project):
        """Return the project's recorded owner, or None."""
        return self._projects.get(normalize_name(project))

    def projects(self):
        """Return registered project names in sorted order."""
        return sorted(self._projects)

    def project_detail(self, project):
        """Return a normalized name and supported namespace metadata."""
        project = normalize_name(project)
        detail = {'name': project}
        if self.supports_namespaces:
            owner = self.project_owner(project)
            matches = [
                {'name': grant.name, 'owned': grant.owner == owner}
                for grant in self.store.matching(project)
            ]
            detail['namespaces'] = matches or None
        return detail

    def _require_namespaces(self):
        if not self.supports_namespaces:
            raise NotSupportedError('repository does not support namespaces')

    def list_namespaces(self):
        """Return the bare /namespaces list, sorted by name."""
        self._require_namespaces()
        return [{'name': name} for name in self.store.namespaces()]

    def namespace_detail(self, namespace):
        """Return the /namespace/<namespace> mapping for an active grant."""
        self._require_namespaces()
        grant = self.store.get(namespace)
        if grant is None:
            raise UnknownGrantError(f'unknown grant: {namespace!r}')
        return {
            'name': grant.name,
            'parent': self.store.parent(grant.name),
            'children': self.store.children(grant.name),
            'owner': grant.owner,
        }

    def simple_html(self, project, files=()):
        """Render an HTML Simple API page without namespace metadata.

        Each file is a mapping with 'filename' and 'url' string values.
        Files are rendered in the order supplied by the caller.
